    {
      "id": "c:4841874358",
      "kind": "maintenance",
      "harm": "premature unmerged libmultiprocess subtree PR included ahead of upstream merge causes CI lint failure",
      "quote": "Also it looks like the subtree is based on https://github.com/bitcoin-core/libmultiprocess/pull/269, which is still open. So this PR should be draft.",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "c:4865377298",
        "c:4948562369"
      ],
      "fix_pushed": true,
      "settled_by_id": "c:4948562369",
      "settled_by_quote": "Subtree PR adding the max connections PR has been merged and added to core"
    },
    {
      "id": "rc:3483064497",
      "kind": "safety",
      "harm": "missing upper bound check allows large connection limits to overflow integer FD reservation and crash on startup",
      "quote": "I believe it would be worth to add an upper bound check too because large values flow into the int FD reservation and overflow it",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3492324764"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3492324764",
      "settled_by_quote": "Changed this to 1 for the lower bound and added an upper bound check."
    },
    {
      "id": "rc:3590927396",
      "kind": "interface",
      "harm": "using colon as options separator conflicts with Windows filesystem paths containing drive letters",
      "quote": "I do really think the ':' options separator should be replaced by ',' to avoid problems with windows paths",
      "blocking": true,
      "status": "resolved",
      "author_replies": [
        "rc:3637872183",
        "c:5062000336"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3637872183",
      "settled_by_quote": "Addressed. socket options now use a comma separator, updated the PR description as well"
    },
    {
      "id": "rc:3633643762",
      "kind": "correctness",
      "harm": "size_t underflow and int overflow in FD accounting arithmetic bypass validation or cause assert crashes on startup",
      "quote": "size_t underflow lets the aggregate check pass... The node starts up with min_required_fds reduced by 2 instead of failing",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3638097846"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3638097846",
      "settled_by_quote": "I took your suggestion and capped IPC connections at 1 << 20, applied the same limit during parsing, and changed the aggregate check to avoid unsigned underflow."
    },
    {
      "id": "rc:3757259791",
      "kind": "correctness",
      "harm": "unix socket paths containing commas cannot be reliably parsed without an escaping mechanism",
      "quote": "The current implementation will accept unix:path,backup.sock=1 as valid when it should fail with Unknown socket option 'backup.sock'.",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3790097164",
        "rc:3903303872"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3903303872",
      "settled_by_quote": "Updated to use the previous solution"
    },
    {
      "id": "rc:3883706613",
      "kind": "interface",
      "harm": "resolved socket path is lost in listener logging and error messages, showing only the unexpanded argument",
      "quote": "This regresses the listener log line: before: Listening for IPC requests on address unix:/home/vinicius/.bitcoin/regtest/node.sock after: Listening for IPC requests on address unix",
      "blocking": false,
      "status": "resolved",
      "author_replies": [
        "rc:3885982359"
      ],
      "fix_pushed": true,
      "settled_by_id": "rc:3885982359",
      "settled_by_quote": "I changed listenAddress to update ListenAddress::address directly, so the resolved socket path is now available to both the log and bind error message."
    }
  ],
